<div class="card">
    <div class="card-header border-bottom border-dashed"><h4 class="header-title mb-0">Data Tagihan Siswa</h4></div>
    <div class="card-body">
        <div class="row g-2 mb-3">
            <div class="col-lg-3"><label class="form-label">Cari Tagihan / Siswa</label><input id="tg-search" class="form-control" placeholder="Nama, NIS atau nomor tagihan"></div>
            <div class="col-lg-2"><label class="form-label">Tahun Pelajaran</label><select id="tg-period" class="form-select"><option value="">Semua Tahun</option><?php foreach ($periode as $p): ?><option value="<?= (int)$p['id'] ?>"><?= html_escape($p['periode']) ?></option><?php endforeach; ?></select></div>
            <div class="col-lg-2"><label class="form-label">Kelas</label><select id="tg-class" class="form-select"><option value="">Semua Kelas</option></select></div>
            <div class="col-lg-2"><label class="form-label">Jenis Tagihan</label><select id="tg-kind" class="form-select"><option value="">Semua Jenis</option><?php foreach ($jenis as $j): ?><option value="<?= (int)$j['id'] ?>"><?= html_escape($j['nama_jenis']) ?></option><?php endforeach; ?></select></div>
            <div class="col-lg-2"><label class="form-label">Status</label><select id="tg-status" class="form-select"><option value="">Semua Status</option><option>Belum Dibayar</option><option>Dibayar Sebagian</option><option>Lunas</option><option>Dibebaskan</option></select></div>
            <div class="col-lg-1 d-flex align-items-end"><button type="button" id="tg-filter" class="btn btn-primary w-100">Cari</button></div>
        </div>
        <div id="tg-summary" class="text-muted small mb-3"></div><div id="tg-list"></div>
        <div class="d-flex align-items-center justify-content-between flex-wrap gap-2 mt-3"><ul class="pagination pagination-sm pagination-boxed mb-0" id="tg-pages"></ul><div class="d-flex align-items-center gap-2"><span>Tampilkan</span><select id="tg-limit" class="form-select form-select-sm" style="width:85px"><option>10</option><option>25</option><option>50</option><option>100</option></select><span>entri</span></div></div>
    </div>
</div>
<div class="modal fade" id="tg-modal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Detail Tagihan Siswa</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body" id="tg-detail"></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Tutup</button></div></div></div></div>
<script>
(function(){'use strict';
const api=<?= json_encode(site_url('admin/tagihan/data_tagihan/')) ?>;
const el=id=>document.getElementById(id), fmt=n=>'Rp'+Number(n||0).toLocaleString('id-ID'), esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows=[],page=1;
function post(action,data){return fetch(api+action,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},credentials:'same-origin',body:new URLSearchParams(data)}).then(async r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()});}
function render(){const size=Number(el('tg-limit').value),max=Math.max(1,Math.ceil(rows.length/size));page=Math.min(max,page);el('tg-summary').textContent=rows.length+' tagihan ditemukan';el('tg-list').innerHTML=rows.slice((page-1)*size,page*size).map((r,i)=>{const title=esc(r.nama_tagihan||r.nama_jenis_tagihan||'-'),s=esc(r.status_pembayaran||'-'),cls=r.status_pembayaran==='Lunas'?'bg-success':r.status_pembayaran==='Dibayar Sebagian'?'bg-warning text-dark':r.status_pembayaran==='Dibebaskan'?'bg-info':'bg-secondary';return `<div class="card-mapel"><p class="keterangan-hari">${esc(r.no_tagihan||'-')} · ${esc(r.periode||'-')} · <span class="badge ${cls}">${s}</span></p><div class="keterangan-mapel"><div class="keterangan-mapel-kiri"><h5 class="judul-mapel" style="margin:0;margin-top:8px">${(page-1)*size+i+1}. ${esc(r.nama_siswa||'-')}</h5><p class="keterangan-jam-mapel">${esc(r.nis||'-')} · ${esc(r.nama_kelas||'-')} · ${title}</p><p class="keterangan-jam-mapel">${esc(r.nama_bulan||'')} ${esc(r.tahun||'')} · Tagihan: ${fmt(r.nominal_tagihan)} · Dibayar: ${fmt(r.nominal_dibayar)} · <strong>Sisa: ${fmt(r.sisa_tagihan)}</strong></p></div><div class="keterangan-mapel-kanan"><button class="btn btn-sm btn-outline-primary" data-detail="${Number(r.id)}"><i class="ri-eye-line"></i> Detail</button></div></div></div>`}).join('')||'<div class="card-mapel"><div class="keterangan-mapel"><h5 class="judul-mapel">Tidak ada data tagihan</h5></div></div>';
let pages='';const a=Math.max(1,page-2),b=Math.min(max,page+2);pages+=`<li class="page-item ${page===1?'disabled':''}"><button class="page-link" data-page="${page-1}">‹</button></li>`;for(let i=a;i<=b;i++)pages+=`<li class="page-item ${page===i?'active':''}"><button class="page-link" data-page="${i}">${i}</button></li>`;pages+=`<li class="page-item ${page===max?'disabled':''}"><button class="page-link" data-page="${page+1}">›</button></li>`;el('tg-pages').innerHTML=pages;}
function load(){el('tg-list').textContent='Memuat tagihan...';post('result',{search:el('tg-search').value,id_periode:el('tg-period').value,id_kelas_setting:el('tg-class').value,id_jenis_tagihan:el('tg-kind').value,status_pembayaran:el('tg-status').value}).then(r=>{rows=Array.isArray(r)?r:[];page=1;render()}).catch(e=>{el('tg-list').textContent='Gagal memuat tagihan: '+e.message;});}
function loadClass(){post('kelas_result',{id_periode:el('tg-period').value}).then(a=>{el('tg-class').innerHTML='<option value="">Semua Kelas</option>'+(Array.isArray(a)?a:[]).map(r=>`<option value="${Number(r.id)}">${esc(r.nama_kelas)}</option>`).join('');}).catch(()=>{el('tg-class').innerHTML='<option value="">Semua Kelas</option>';});}
function detail(id){post('detail',{id}).then(r=>{if(r.result!=='true')throw Error(r.message||'Data tidak ditemukan');const t=r.tagihan,history=(r.pembayaran||[]).map(h=>`<div class="border rounded p-2 mb-2"><div class="d-flex justify-content-between"><span>${esc(h.tanggal_transaksi)} · ${esc(h.no_transaksi||'')}</span><strong>${fmt(h.nominal_bayar)}</strong></div><small>${esc(h.nama_metode_pembayaran||'')} · ${esc(h.status_transaksi||'')}</small></div>`).join('');el('tg-detail').innerHTML=`<h5>${esc(t.nama_siswa)} · ${esc(t.nis)}</h5><p>${esc(t.nama_tagihan)} · ${esc(t.no_tagihan)} · ${esc(t.periode)}</p><div class="row g-2 mb-3"><div class="col-4">Tagihan<br><strong>${fmt(t.nominal_tagihan)}</strong></div><div class="col-4">Dibayar<br><strong>${fmt(t.nominal_dibayar)}</strong></div><div class="col-4">Sisa<br><strong>${fmt(t.sisa_tagihan)}</strong></div></div><h6>Riwayat Angsuran</h6>${history||'<p class="text-muted">Belum ada pembayaran.</p>'}`;bootstrap.Modal.getOrCreateInstance(el('tg-modal')).show()}).catch(e=>alert(e.message));}
el('tg-filter').onclick=load;el('tg-period').onchange=()=>{loadClass();load()};el('tg-limit').onchange=()=>{page=1;render()};el('tg-search').onkeydown=e=>{if(e.key==='Enter')load()};el('tg-pages').onclick=e=>{const b=e.target.closest('[data-page]');if(b){const n=Number(b.dataset.page);if(n>0&&n<=Math.ceil(rows.length/Number(el('tg-limit').value))){page=n;render()}}};el('tg-list').onclick=e=>{const b=e.target.closest('[data-detail]');if(b)detail(Number(b.dataset.detail))};loadClass();load();
})();
</script>
